function applyLang(lang){
  if (!I18N[lang]) lang = 'en';
  var dict = I18N[lang];
  var fallback = I18N.en;
  document.documentElement.lang = lang;
  document.documentElement.dir = RTL_LANGS[lang] ? 'rtl' : 'ltr';
  document.querySelectorAll('[data-i18n]').forEach(function(el){
    var key = el.getAttribute('data-i18n');
    var val = dict[key] !== undefined ? dict[key] : fallback[key];
    if (val !== undefined) el.innerHTML = val;
  });
  document.title = dict.title || fallback.title;
  var sel = document.getElementById('langSelect');
  if (sel) sel.value = lang;
  try { localStorage.setItem('ct-lang', lang); } catch (e) {}
}

document.addEventListener('DOMContentLoaded', function(){
  var sel = document.getElementById('langSelect');
  if (sel) sel.addEventListener('change', function(){ applyLang(this.value); });
  var saved = 'en';
  try { saved = localStorage.getItem('ct-lang') || 'en'; } catch (e) {}
  applyLang(saved);
});
